input.script:
companies = list_companies({})
company_map = fold acc = {} for c in companies { return acc + { [c.domain]: c.name } }

page1 = boundary retry 2 { return list_contacts({ page: 1 }) } catch err { return fail("LIST_FAILED", err.message) }
page2 = boundary retry 2 { return list_contacts({ page: 2 }) } catch err { return fail("LIST_FAILED", err.message) }
page3 = boundary retry 2 { return list_contacts({ page: 3 }) } catch err { return fail("LIST_FAILED", err.message) }

contacts = page1.items + page2.items + page3.items

results = for contact in contacts {
    phone_needs_fix = not regex.test(contact.phone, "^\\+1\\d{10}$")
    digits = regex.replace(contact.phone, "[^0-9]", "")
    new_phone = "+1" + digits

    email_parts = text.split(contact.email, "@")
    email_domain = email_parts[1] if list.length(email_parts) > 1 else ""
    company_needs_fill = contact.company == "" and email_domain in company_map
    new_company = company_map[email_domain] if company_needs_fill else null

    should_update = phone_needs_fix or company_needs_fill

    result = update_contact({
        id: contact.id,
        phone: new_phone if phone_needs_fix else null,
        company: new_company if company_needs_fill else null
    }) if should_update else null

    return {
        phone_fixed: phone_needs_fix,
        company_filled: company_needs_fill
    }
}

phones_fixed = fold acc = 0 for r in results { return acc + (1 if r.phone_fixed else 0) }
companies_filled = fold acc = 0 for r in results { return acc + (1 if r.company_filled else 0) }

return submit_result({ answer: { phones_fixed, companies_filled } })
